// Copy of supabase/functions/_shared/schedule.ts (keep both in sync) plus app helpers.
// Parses the free-text "horario" stored on events (generated by the admin as
// "Martes · 19h", "Lunes y Jueves · 7:30 PM", "Diario · 20h30", plus older
// variants like "Sábados · 3:00 PM") and finds the occurrence that has just
// started in the event's time zone.

export type ParsedSchedule = {
  days: number[]; // 0 = domingo ... 6 = sábado
  minutes: number; // minutes after local midnight
};

const DAY_INDEX: Record<string, number> = {
  domingo: 0,
  lunes: 1,
  martes: 2,
  miercoles: 3,
  jueves: 4,
  viernes: 5,
  sabado: 6,
};

function normalize(value: string) {
  return value.normalize("NFD").replace(/[̀-ͯ]/g, "").toLowerCase();
}

export function parseTime(text: string): number | null {
  const value = normalize(text);

  const twelve = value.match(/\b(1[0-2]|0?[1-9])(?::([0-5]\d))?\s*([ap])\.?\s*m\.?(?![a-z])/);
  if (twelve) {
    let hour = Number(twelve[1]) % 12;
    if (twelve[3] === "p") hour += 12;
    return hour * 60 + Number(twelve[2] || 0);
  }

  const european = value.match(/\b([01]?\d|2[0-3])\s*h\s*([0-5]\d)?\b/);
  if (european) return Number(european[1]) * 60 + Number(european[2] || 0);

  const clock = value.match(/\b([01]?\d|2[0-3]):([0-5]\d)\b/);
  if (clock) return Number(clock[1]) * 60 + Number(clock[2]);

  return null;
}

export function parseDays(text: string): number[] {
  const value = normalize(text);
  if (/\b(diario|diariamente|todos los dias|cada dia)\b/.test(value)) return [0, 1, 2, 3, 4, 5, 6];
  if (/\b(lunes a viernes|entre semana)\b/.test(value)) return [1, 2, 3, 4, 5];

  const found = new Set<number>();
  for (const [name, index] of Object.entries(DAY_INDEX)) {
    if (new RegExp(`\\b${name}s?\\b`).test(value)) found.add(index);
  }
  return [...found].sort();
}

export function parseSchedule(horario: string | null | undefined): ParsedSchedule | null {
  const text = String(horario || "").trim();
  if (!text) return null;
  const minutes = parseTime(text);
  const days = parseDays(text);
  if (minutes === null || days.length === 0) return null;
  return { days, minutes };
}

type LocalParts = { year: number; month: number; day: number; hour: number; minute: number; weekday: number };

const WEEKDAYS = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];

function localParts(instant: Date, timeZone: string): LocalParts {
  const parts = new Intl.DateTimeFormat("en-US", {
    timeZone,
    hourCycle: "h23",
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
    weekday: "short",
  }).formatToParts(instant);
  const get = (type: string) => parts.find((part) => part.type === type)?.value || "";
  return {
    year: Number(get("year")),
    month: Number(get("month")),
    day: Number(get("day")),
    hour: Number(get("hour")) % 24,
    minute: Number(get("minute")),
    weekday: WEEKDAYS.indexOf(get("weekday")),
  };
}

// Converts a wall-clock time in `timeZone` to a UTC instant.
function zonedToUtc(year: number, month: number, day: number, minutes: number, timeZone: string): Date {
  const guess = Date.UTC(year, month - 1, day, Math.floor(minutes / 60), minutes % 60);
  // Two passes handle DST boundaries.
  let utc = guess;
  for (let i = 0; i < 2; i += 1) {
    const p = localParts(new Date(utc), timeZone);
    const asUtc = Date.UTC(p.year, p.month - 1, p.day, p.hour, p.minute);
    utc = guess - (asUtc - utc);
  }
  return new Date(utc);
}

export function isValidTimeZone(timeZone: string) {
  try {
    new Intl.DateTimeFormat("en-US", { timeZone });
    return true;
  } catch {
    return false;
  }
}

/**
 * Returns the UTC start of the occurrence that began within the last
 * `windowMinutes` (inclusive of "just now"), or null if none did.
 */
export function startedOccurrence(
  schedule: ParsedSchedule,
  timeZone: string,
  now: Date,
  windowMinutes = 10,
): Date | null {
  // Look at local "today" and "yesterday" so meetings just before midnight still count.
  for (const offsetDays of [0, -1]) {
    const probe = new Date(now.getTime() + offsetDays * 86_400_000);
    const local = localParts(probe, timeZone);
    if (!schedule.days.includes(local.weekday)) continue;
    const start = zonedToUtc(local.year, local.month, local.day, schedule.minutes, timeZone);
    const elapsed = now.getTime() - start.getTime();
    if (elapsed >= 0 && elapsed <= windowMinutes * 60_000) return start;
  }
  return null;
}

/** Next occurrence start (UTC) at or after `now - liveMinutes`, looking up to 8 days ahead. */
export function nextOccurrence(schedule: ParsedSchedule, timeZone: string, now: Date, liveMinutes = 90): Date | null {
  const from = now.getTime() - liveMinutes * 60_000;
  for (let offsetDays = -1; offsetDays <= 8; offsetDays += 1) {
    const probe = new Date(now.getTime() + offsetDays * 86_400_000);
    const local = localParts(probe, timeZone);
    if (!schedule.days.includes(local.weekday)) continue;
    const start = zonedToUtc(local.year, local.month, local.day, schedule.minutes, timeZone);
    if (start.getTime() >= from) return start;
  }
  return null;
}

/** App helper: every occurrence start (UTC) between `from` and `to`. */
export function occurrencesBetween(schedule: ParsedSchedule, timeZone: string, from: Date, to: Date): Date[] {
  const out: Date[] = [];
  const days = Math.ceil((to.getTime() - from.getTime()) / 86_400_000) + 1;
  for (let offsetDays = -1; offsetDays <= days; offsetDays += 1) {
    const probe = new Date(from.getTime() + offsetDays * 86_400_000);
    const local = localParts(probe, timeZone);
    if (!schedule.days.includes(local.weekday)) continue;
    const start = zonedToUtc(local.year, local.month, local.day, schedule.minutes, timeZone);
    if (start >= from && start < to && !out.some((d) => d.getTime() === start.getTime())) out.push(start);
  }
  return out;
}
